END;

DROP TRIGGER trg_stocktakes_day_closed_complete;
CREATE TRIGGER trg_stocktakes_day_closed_complete
BEFORE UPDATE OF status ON stocktakes
WHEN NEW.status = 'completed' AND OLD.status <> 'completed'
  AND EXISTS (SELECT 1 FROM daily_closings d WHERE d.book = OLD.book AND d.segment IS OLD.segment AND d.business_date >= OLD.business_date AND (d.reopened_at IS NULL OR d.closed_at > d.reopened_at))
BEGIN
  SELECT CASE
    WHEN EXISTS (SELECT 1 FROM daily_closings d WHERE d.book = OLD.book AND d.segment IS OLD.segment AND d.business_date = OLD.business_date AND (d.reopened_at IS NULL OR d.closed_at > d.reopened_at))
    THEN RAISE(ABORT, 'DAY_CLOSED')
    ELSE RAISE(ABORT, 'BACKDATE_BEFORE_CLOSED_DAY')
  END;
END;

DROP TRIGGER trg_stocktakes_day_closed_void;
CREATE TRIGGER trg_stocktakes_day_closed_void
BEFORE UPDATE OF status ON stocktakes
WHEN OLD.status = 'completed' AND NEW.status = 'void'
  AND EXISTS (SELECT 1 FROM daily_closings d WHERE d.book = OLD.book AND d.segment IS OLD.segment AND d.business_date >= OLD.business_date AND (d.reopened_at IS NULL OR d.closed_at > d.reopened_at))
BEGIN
  SELECT CASE
    WHEN EXISTS (SELECT 1 FROM daily_closings d WHERE d.book = OLD.book AND d.segment IS OLD.segment AND d.business_date = OLD.business_date AND (d.reopened_at IS NULL OR d.closed_at > d.reopened_at))
    THEN RAISE(ABORT, 'DAY_CLOSED')
    ELSE RAISE(ABORT, 'BACKDATE_BEFORE_CLOSED_DAY')
  END;
END;

DROP TRIGGER trg_opening_stock_batches_day_closed;
CREATE TRIGGER trg_opening_stock_batches_day_closed
BEFORE INSERT ON opening_stock_batches
WHEN EXISTS (SELECT 1 FROM daily_closings d WHERE d.book = 'shop' AND d.segment IS NULL AND d.business_date >= NEW.business_date AND (d.reopened_at IS NULL OR d.closed_at > d.reopened_at))
 AND EXISTS (SELECT 1 FROM daily_closings d WHERE d.book = 'telecom' AND d.segment IS 'dialog_cards' AND d.business_date >= NEW.business_date AND (d.reopened_at IS NULL OR d.closed_at > d.reopened_at))
 AND EXISTS (SELECT 1 FROM daily_closings d WHERE d.book = 'telecom' AND d.segment IS 'mobitel_cards' AND d.business_date >= NEW.business_date AND (d.reopened_at IS NULL OR d.closed_at > d.reopened_at))
 AND EXISTS (SELECT 1 FROM daily_closings d WHERE d.book = 'telecom' AND d.segment IS 'airtel_cards' AND d.business_date >= NEW.business_date AND (d.reopened_at IS NULL OR d.closed_at > d.reopened_at))
 AND EXISTS (SELECT 1 FROM daily_closings d WHERE d.book = 'telecom' AND d.segment IS 'hutch_cards' AND d.business_date >= NEW.business_date AND (d.reopened_at IS NULL OR d.closed_at > d.reopened_at))
BEGIN
  SELECT CASE
    WHEN EXISTS (SELECT 1 FROM daily_closings d WHERE d.book = 'shop' AND d.segment IS NULL AND d.business_date = NEW.business_date AND (d.reopened_at IS NULL OR d.closed_at > d.reopened_at))
      OR EXISTS (SELECT 1 FROM daily_closings d WHERE d.book = 'telecom' AND d.segment IS 'dialog_cards' AND d.business_date = NEW.business_date AND (d.reopened_at IS NULL OR d.closed_at > d.reopened_at))
      OR EXISTS (SELECT 1 FROM daily_closings d WHERE d.book = 'telecom' AND d.segment IS 'mobitel_cards' AND d.business_date = NEW.business_date AND (d.reopened_at IS NULL OR d.closed_at > d.reopened_at))
      OR EXISTS (SELECT 1 FROM daily_closings d WHERE d.book = 'telecom' AND d.segment IS 'airtel_cards' AND d.business_date = NEW.business_date AND (d.reopened_at IS NULL OR d.closed_at > d.reopened_at))
      OR EXISTS (SELECT 1 FROM daily_closings d WHERE d.book = 'telecom' AND d.segment IS 'hutch_cards' AND d.business_date = NEW.business_date AND (d.reopened_at IS NULL OR d.closed_at > d.reopened_at))
    THEN RAISE(ABORT, 'DAY_CLOSED')
    ELSE RAISE(ABORT, 'BACKDATE_BEFORE_CLOSED_DAY')
  END;
END;

DROP TRIGGER trg_opening_stock_batches_day_closed_void;
CREATE TRIGGER trg_opening_stock_batches_day_closed_void
BEFORE UPDATE OF status ON opening_stock_batches
WHEN OLD.status = 'posted' AND NEW.status = 'void'
  AND EXISTS (SELECT 1 FROM stock_movements m
                JOIN v_product_segment v ON v.product_id = m.product_id
                JOIN daily_closings d ON d.book = v.book AND d.segment IS v.segment
               WHERE m.ref_table = 'opening_stock_batches' AND m.ref_id = OLD.id AND d.business_date >= OLD.business_date AND (d.reopened_at IS NULL OR d.closed_at > d.reopened_at))
BEGIN
  SELECT CASE
    WHEN EXISTS (SELECT 1 FROM stock_movements m
                JOIN v_product_segment v ON v.product_id = m.product_id
                JOIN daily_closings d ON d.book = v.book AND d.segment IS v.segment
               WHERE m.ref_table = 'opening_stock_batches' AND m.ref_id = OLD.id AND d.business_date = OLD.business_date AND (d.reopened_at IS NULL OR d.closed_at > d.reopened_at))
    THEN RAISE(ABORT, 'DAY_CLOSED')
    ELSE RAISE(ABORT, 'BACKDATE_BEFORE_CLOSED_DAY')
  END;
END;

-- ===== (2) consistency =====
-- the cash entry of a record carries that record's segment (a reversal is judged by trg_cash_entries_reversal_mirror)
CREATE TRIGGER trg_cash_entries_segment_matches_ref
BEFORE INSERT ON cash_entries
WHEN NEW.reverses_entry_id IS NULL AND NEW.ref_table IS NOT NULL AND (
  (NEW.ref_table = 'sales' AND EXISTS (SELECT 1 FROM sales o WHERE o.id = NEW.ref_id AND o.segment IS NOT NEW.segment))
  OR   (NEW.ref_table = 'sales_returns' AND EXISTS (SELECT 1 FROM sales_returns r JOIN sales o ON o.id = r.sale_id WHERE r.id = NEW.ref_id AND o.segment IS NOT NEW.segment))
  OR   (NEW.ref_table = 'purchases' AND EXISTS (SELECT 1 FROM purchases o WHERE o.id = NEW.ref_id AND o.segment IS NOT NEW.segment))
  OR   (NEW.ref_table = 'purchase_returns' AND EXISTS (SELECT 1 FROM purchase_returns r JOIN purchases o ON o.id = r.purchase_id WHERE r.id = NEW.ref_id AND o.segment IS NOT NEW.segment))
  OR   (NEW.ref_table = 'expenses' AND EXISTS (SELECT 1 FROM expenses o WHERE o.id = NEW.ref_id AND o.segment IS NOT NEW.segment))
  OR   (NEW.ref_table = 'capital_entries' AND EXISTS (SELECT 1 FROM capital_entries o WHERE o.id = NEW.ref_id AND o.segment IS NOT NEW.segment))
  OR   (NEW.ref_table = 'owner_drawings' AND EXISTS (SELECT 1 FROM owner_drawings o WHERE o.id = NEW.ref_id AND o.segment IS NOT NEW.segment))
  OR   (NEW.ref_table = 'cash_counts' AND EXISTS (SELECT 1 FROM cash_counts o WHERE o.id = NEW.ref_id AND o.segment IS NOT NEW.segment))
  OR   (NEW.ref_table = 'reload_sales' AND EXISTS (SELECT 1 FROM reload_sales o WHERE o.id = NEW.ref_id AND o.segment IS NOT NEW.segment))
  OR   (NEW.ref_table = 'ezcash_sales' AND EXISTS (SELECT 1 FROM ezcash_sales o WHERE o.id = NEW.ref_id AND o.segment IS NOT NEW.segment))
  OR   (NEW.ref_table = 'telecom_topups' AND EXISTS (SELECT 1 FROM telecom_topups o WHERE o.id = NEW.ref_id AND o.segment IS NOT NEW.segment)))
BEGIN
  SELECT RAISE(ABORT, 'SEGMENT_MISMATCH');
END;

-- reload / EZCash / top-up rows: the segment comes from the provider (EZCash and wallet top-ups are Dialog Reloads)
CREATE TRIGGER trg_reload_sales_segment_provider
BEFORE INSERT ON reload_sales
WHEN NEW.segment IS NOT (SELECT lower(p.name) || '_reloads' FROM reload_providers p WHERE p.id = NEW.provider_id)
BEGIN
  SELECT RAISE(ABORT, 'SEGMENT_MISMATCH');
END;

CREATE TRIGGER trg_ezcash_sales_segment_provider
BEFORE INSERT ON ezcash_sales
WHEN NEW.segment IS NOT (SELECT lower(p.name) || '_reloads' FROM reload_providers p WHERE p.id = NEW.provider_id)
BEGIN
  SELECT RAISE(ABORT, 'SEGMENT_MISMATCH');
END;

CREATE TRIGGER trg_telecom_topups_segment_provider
BEFORE INSERT ON telecom_topups
WHEN NEW.segment IS NOT CASE WHEN NEW.provider_id IS NULL THEN 'dialog_reloads'
                             ELSE (SELECT lower(p.name) || '_reloads' FROM reload_providers p WHERE p.id = NEW.provider_id) END
BEGIN
  SELECT RAISE(ABORT, 'SEGMENT_MISMATCH');
END;

-- lines carry the segment of their product (the header is inserted first)
CREATE TRIGGER trg_sale_items_segment_matches
BEFORE INSERT ON sale_items
WHEN EXISTS (SELECT 1 FROM sales s JOIN v_product_segment v ON v.product_id = NEW.product_id
              WHERE s.id = NEW.sale_id AND (v.book IS NOT s.book OR v.segment IS NOT s.segment))
BEGIN
  SELECT RAISE(ABORT, 'SEGMENT_MISMATCH');
END;

CREATE TRIGGER trg_purchase_items_segment_matches
BEFORE INSERT ON purchase_items
WHEN EXISTS (SELECT 1 FROM purchases h JOIN v_product_segment v ON v.product_id = NEW.product_id
              WHERE h.id = NEW.purchase_id AND (v.book IS NOT h.book OR v.segment IS NOT h.segment))
BEGIN
  SELECT RAISE(ABORT, 'SEGMENT_MISMATCH');
END;

CREATE TRIGGER trg_stocktake_items_segment_matches
BEFORE INSERT ON stocktake_items
WHEN EXISTS (SELECT 1 FROM stocktakes h JOIN v_product_segment v ON v.product_id = NEW.product_id
              WHERE h.id = NEW.stocktake_id AND (v.book IS NOT h.book OR v.segment IS NOT h.segment))
BEGIN
  SELECT RAISE(ABORT, 'SEGMENT_MISMATCH');
END;

CREATE TRIGGER trg_stock_losses_segment_matches
BEFORE INSERT ON stock_losses
WHEN EXISTS (SELECT 1 FROM v_product_segment v WHERE v.product_id = NEW.product_id AND (v.book IS NOT NEW.book OR v.segment IS NOT NEW.segment))
BEGIN
  SELECT RAISE(ABORT, 'SEGMENT_MISMATCH');
END;

CREATE TRIGGER trg_owner_drawings_segment_matches_product
BEFORE INSERT ON owner_drawings
WHEN NEW.kind = 'goods' AND NEW.book = 'telecom'
 AND EXISTS (SELECT 1 FROM v_product_segment v WHERE v.product_id = NEW.product_id AND v.segment IS NOT NEW.segment)
BEGIN
  SELECT RAISE(ABORT, 'SEGMENT_MISMATCH');
END;

-- ===== guard =====
-- every old trigger still exists (same names), exactly the new consistency triggers were added, nothing else.
CREATE TEMP TABLE _mig026_new (name TEXT NOT NULL);
INSERT INTO _mig026_new VALUES ('trg_cash_entries_segment_matches_ref');
INSERT INTO _mig026_new VALUES ('trg_reload_sales_segment_provider');
INSERT INTO _mig026_new VALUES ('trg_ezcash_sales_segment_provider');
INSERT INTO _mig026_new VALUES ('trg_telecom_topups_segment_provider');
INSERT INTO _mig026_new VALUES ('trg_sale_items_segment_matches');
INSERT INTO _mig026_new VALUES ('trg_purchase_items_segment_matches');
INSERT INTO _mig026_new VALUES ('trg_stocktake_items_segment_matches');
INSERT INTO _mig026_new VALUES ('trg_stock_losses_segment_matches');
INSERT INTO _mig026_new VALUES ('trg_owner_drawings_segment_matches_product');
CREATE TEMP TABLE _mig026_guard (ok INTEGER NOT NULL CHECK (ok = 1));
INSERT INTO _mig026_guard SELECT CASE WHEN
      NOT EXISTS (SELECT 1 FROM _mig026_objs o WHERE NOT EXISTS (SELECT 1 FROM sqlite_master m WHERE m.type = o.type AND m.name = o.name))
  AND NOT EXISTS (SELECT 1 FROM _mig026_new w WHERE NOT EXISTS (SELECT 1 FROM sqlite_master m WHERE m.type = 'trigger' AND m.name = w.name))
  AND (SELECT COUNT(*) FROM sqlite_master WHERE type IN ('index','trigger','view') AND name NOT LIKE 'sqlite_autoindex%') = (SELECT COUNT(*) FROM _mig026_objs) + (SELECT COUNT(*) FROM _mig026_new)
  AND (SELECT COUNT(*) FROM sqlite_master WHERE type = 'trigger' AND name LIKE 'trg\_%\_day\_closed%' ESCAPE '\' AND tbl_name NOT LIKE 'icecream%' AND tbl_name NOT LIKE 'print%'
        AND sql LIKE '%d.segment IS%') = 32
  AND NOT EXISTS (SELECT 1 FROM pragma_foreign_key_check)
  THEN 1 ELSE 0 END;

DROP TABLE _mig026_guard;
DROP TABLE _mig026_new;
DROP TABLE _mig026_objs;
